detection_code:
// model_loader.cpp, inside the `for (auto& [name, tensor_storage] : tensor_storage_map)`
// detection loop in get_sd_version(...). Place it next to the other DiT name checks
// (e.g. right after the `embed_image_indicator.weight` -> VERSION_IDEOGRAM4 check).
// Copied verbatim from upstream/master:src/model_loader.cpp (handles both the
// ostris "txtfusion" and the alt "text_fusion" tensor naming).
if (tensor_storage.name.find("model.diffusion_model.txtfusion.projector.weight") != std::string::npos ||
    tensor_storage.name.find("model.diffusion_model.text_fusion.projector.weight") != std::string::npos) {
    return VERSION_KREA2;
}

