//        VERSION_WAN_S2V,
//        VERSION_KREA2,      // <-- add
//        VERSION_COUNT,
//    NOTE: model_version_to_str[] in stable-diffusion.cpp MUST get a matching "Krea2"
//    entry in the SAME position (see extra_integration) or the arrays desync.
//
// 2) HELPER (add near the other sd_version_is_* helpers, e.g. after sd_version_is_ideogram4):
static inline bool sd_version_is_krea2(SDVersion version) {
    if (version == VERSION_KREA2) {
        return true;
    }
    return false;
}
//
// 3) CATEGORY MEMBERSHIP — add krea2 to sd_version_is_dit(...) (append to the OR chain,
//    before the closing `) {`):
//        sd_version_is_ideogram4(version) ||
//        sd_version_is_krea2(version)) {
//
// 4) VAE: the fork has NO sd_version_uses_wan_vae() / sd_version_uses_*_vae() family for
//    this path — VAE selection lives in stable-diffusion.cpp's create_vae lambda, NOT in
//    model.h. Do NOT add a uses_wan_vae helper. See the `vae` field for the create_vae edit.
//    (Only sd_version_uses_flux2_vae exists in this fork and krea2 must NOT be added to it.)

dispatch_case:
// stable-diffusion.cpp, in the cond_stage_model / diffusion_model construction chain
// (the same if/else-if ladder that already has the `sd_version_is_ideogram4` branch).
// Fork convention: backend_for + params_backend_for, NO model_manager arg.
// LLMEmbedder last bool (enable_vision) = true for krea2 (ideogram4 passes false).
} else if (sd_version_is_krea2(version)) {
    cond_stage_model = std::make_shared<LLMEmbedder>(backend_for(SDBackendModule::TE),
                                                     params_backend_for(SDBackendModule::TE),
                                                     tensor_storage_map,
                                                     version,
                                                     "",
                                                     true);
    diffusion_model  = std::make_shared<Krea2::Krea2Runner>(backend_for(SDBackendModule::DIFFUSION),
                                                           params_backend_for(SDBackendModule::DIFFUSION),
                                                           tensor_storage_map,
                                                           "model.diffusion_model");
}

